{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "In dogs, the absolute oral bioavailability of menaquinone-4 (MK-4), a close isoprenoid-quinone analogue, was 13.5% of IV AUC after a soft-capsule formulation in non-fasted conditions, directly supporting F <20% for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Oral MK-4 alone in bile-duct-cannulated rats showed almost no absorption because mixed micelles are not formed, indicating that absorption of isoprenoid quinones is highly bile-dependent and intrinsically poor without formulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed only 0.17% systemic availability after oral tomato paste in humans, supporting low F for large lipophilic isoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol-rich palm oil fraction had poor oral bioavailability in humans, supporting low F for lipophilic isoprenoid natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a non-conjugated C40 isoprenoid hydrocarbon, had 58.5% absolute bioavailability in humans, showing that some highly lipophilic isoprenoids can be well absorbed; this contradicts a low prediction but is limited by phytoene's lower molecular weight and lack of a quinone head.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "MK-7 has superior bioavailability relative to vitamin K1 due to its extended isoprenoid chain, slower clearance, and higher systemic retention; this suggests longer-chain quinones may have improved exposure, but it is a relative comparison and does not establish F >=20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues with absolute bioavailability data are menaquinones: MK-4 had only 13.5% oral F in dogs, and its absorption is strongly bile-dependent and formulation-sensitive. Although phytoene and MK-7 show that longer/non-conjugated isoprenoid chains can improve exposure, the query's high molecular weight (~727), extreme lipophilicity, and quinone head make F >=20% less likely. Overall evidence supports low oral bioavailability.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule (ubiquinone/CoQ8).",
    "MK-4 absolute F was measured in dogs, not humans; species differences in absorption may exist.",
    "MK-7 'superior bioavailability' is a relative comparison and does not provide an absolute F value relative to the 20% threshold.",
    "Formulation and fed-state effects could raise F above 20% if optimized, but the query's standard oral formulation is unspecified.",
    "Phytoene's high F may not transfer to the query because phytoene lacks the quinone head and has a lower molecular weight."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C31", "C28", "C37", "C32", "C33", "C36", "C30", "C34", "C35", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "menaquinone-4"
    },
    {
      "applicability": "high",
      "card_ids": ["C27"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "menaquinone-7"
    }
  ],
  "revision_action": "strengthen"
}

